def parse_time_utc(s):
    s = s.strip()
    d = dt.datetime.fromisoformat(s.replace('Z', '+00:00').replace('z', '+00:00'))
    if d.tzinfo is not None:
        d = d.astimezone(dt.timezone.utc)
    return d.date()


# record: (num, kind, counted, kg, date)  kind in new/correction/void
def kind_of(s):
    s = (s or '').strip().upper()
    if s.startswith('V'):
        return 'void'
    if s.startswith('C') or s.startswith('A'):
        return 'correction'
    return 'new'


def make(idtxt, kind, status, kg, date):
    n = num_of(idtxt)
    if n is None:
        return None
    return {'num': n, 'kind': kind, 'status': status, 'kg': kg, 'date': date}


# ---------- delimited ----------
CFG = {
    'east': dict(delim=',', quote=True, cols=['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
                 id='id', type='type', date='shipped', weight='gross', status='status',
                 style='us', unit='kg', form='ymd'),
    'lakeside': dict(delim=',', quote=True, cols=['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
                     id='id', type='kind', date='shipped', weight='gross_kg', status='status',
                     style='us', unit='kg', form='iso', fixed_unit='kg'),
    'harbor': dict(delim='|', quote=False, cols=['rec', 'ref', 'date', 'weight', 'state'],
                   id='ref', type='rec', date='date', weight='weight', status='state',
                   style='us', unit='kg', form='iso', inline_unit=True),
    'river': dict(delim='\t', quote=False, cols=['t', 'ref', 'shipped', 'weight', 'status'],
                  id='ref', type='t', date='shipped', weight='weight', status='status',
                  style='us', unit='kg', form='mm/dd/yyyy'),
    'west': dict(delim=';', quote=False, cols=['id', 'typ', 'shipped', 'weight', 'status', 'note'],
                 id='id', type='typ', date='shipped', weight='weight', status='status',
                 style='eu', unit='kg', form='dd.mm.yyyy'),
}


def split_row(line, delim, quote):
    if not quote:
        return line.split(delim)
    out, cur, inq, i = [], [], False, 0
    while i < len(line):
        c = line[i]
        if inq:
            if c == '"':
                if line[i + 1:i + 2] == '"':
                    cur.append('"'); i += 1
                else:
                    inq = False
            else:
                cur.append(c)
        elif c == '"':
            inq = True
        elif c == delim:
            out.append(''.join(cur)); cur = []
        else:
            cur.append(c)
        i += 1
    out.append(''.join(cur))
    return out


def parse_delimited(depot, text):
    cfg = CFG[depot]
    seq = None
    form = cfg['form']
    unit = cfg['unit']
    hdr = None
    colset = set(cfg['cols'])
    recs = []
    buf = None
    for line in lines_of(text):
        if buf is not None:
            buf += '\n' + line
            if buf.count('"') % 2 == 1:
                continue
            line, buf = buf, None
        else:
            if line.startswith('#'):
                m = re.match(r'#\s*([^:=]+?)\s*[:=]\s*(.*)$', line)
                if m:
                    k, v = m.group(1).lower(), m.group(2).strip()
                    if k == 'seq' or k.endswith(' seq'):
                        if seq is None and re.match(r'\d+', v):
                            seq = int(re.match(r'\d+', v).group())
                    elif k in ('dates', 'date format', 'date', 'dateformat'):
                        form = v
                    elif k in ('unit', 'weight unit', 'weight-unit'):
                        unit = norm_unit(v) or unit
                continue
            if line.strip() == '':
                continue
            if cfg['quote'] and line.count('"') % 2 == 1:
                buf = line
                continue
        row = split_row(line, cfg['delim'], cfg['quote'])
        low = [f.strip().lower() for f in row]
        if len(low) >= 2 and all(f in colset for f in low):
            hdr = low
            continue
        if hdr is None:
            continue
        wi = hdr.index(cfg['weight'])
        row_unit = None
        if len(row) == len(hdr) + 1:
            row_unit = norm_unit(row[wi + 1])
            del row[wi + 1]
        row += [''] * (len(hdr) - len(row))
        d = dict(zip(hdr, row))
        idtxt = d.get(cfg['id'], '')
        if not re.match(r'\s*SH\D*\d+\s*$', idtxt, re.I):
            continue  # trailer rows
        kind = kind_of(d.get(cfg['type'], ''))
        if kind == 'void':
            recs.append(make(idtxt, 'void', None, None, None))
            continue
        w = d.get(cfg['weight'], '').strip()
        status = d.get(cfg['status'], '')
        if cfg.get('inline_unit'):
            status = HARBOR_STATES.get(status.strip().upper(), status)
        mu = re.match(r'^([-\d.,]+)\s*([A-Za-z]+)$', w)
        if mu:
            w, wu = mu.group(1), norm_unit(mu.group(2))
        elif cfg.get('fixed_unit'):
            wu = cfg['fixed_unit']
        else:
            wu = row_unit or unit
        try:
            kg = to_kg(parse_weight(w, cfg['style']), wu)
        except Exception:
            kg = None
        try:
            date = parse_date(d.get(cfg['date'], ''), form)
        except Exception:
            date = None
        recs.append(make(idtxt, kind, norm_status(status), kg, date))
    return seq, [r for r in recs if r]


# ---------- XML ----------
def parse_date_text(s):
    s = s.strip()
    if re.match(r'\d{4}-\d\d-\d\d[T ]\d', s):
        return parse_time_utc(s.replace(' ', 'T', 1))
    m = re.match(r'(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$', s)
    if m:
        return dt.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    return parse_date(s, 'iso')


def parse_central(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if (root.get('seq') or '').strip().isdigit() else None
    runit = norm_unit(root.get('weight-unit')) or 'kg'
    recs = []
    for el in root.iter('shipment'):
        idtxt = el.get('id') or (el.findtext('id') or '')
        kind = kind_of(el.get('type') or '')
        if kind == 'void':
            recs.append(make(idtxt, 'void', None, None, None))
            continue
        w = el.find('weight')
        kg = None
        if w is not None and (w.text or '').strip():
            u = norm_unit(w.get('unit')) or norm_unit(el.get('weight-unit')) or runit
            try:
                kg = to_kg(Decimal(w.text.strip().replace(',', '')), u)
            except Exception:
                pass
        sh = el.get('shipped')
        if sh is None:
            sh = el.findtext('shipped')
        try:
            date = parse_date_text(sh)
        except Exception:
            date = None
        recs.append(make(idtxt, kind, norm_status(el.findtext('status') or el.get('status')), kg, date))
    return seq, [r for r in recs if r]


# ---------- JSON lines ----------
def parse_north(text):
    seq = None
    recs = []
    for line in lines_of(text):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and o['meta'].get('seq') is not None:
                    seq = int(o['meta']['seq'])
                continue
            idtxt = str(o.get('id', ''))
            kind = kind_of(o.get('kind') or '')
            if kind == 'void':
                recs.append(make(idtxt, 'void', None, None, None))
                continue
            kg = None
            for k, val in o.items():
                if k.lower().startswith('weight_'):
                    try:
                        kg = to_kg(Decimal(str(val).replace(',', '')), norm_unit(k[7:]))
                    except Exception:
                        pass
                    break
            try:
                date = parse_time_utc(o['shipped_at'])
            except Exception:
                date = None
            recs.append(make(idtxt, kind, norm_status(o.get('status')), kg, date))
    return seq, [r for r in recs if r]


# ---------- fixed width ----------
LAYOUTS = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), date=(10, 17), dfmt='ordinal', w=(17, 25), wu='g', st=(25, 26)),
    'FW2': dict(len=43, id=(1, 10), type=(0, 1), date=(10, 18), dfmt='ymd', w=(18, 26), wu='cg', st=(26, 27)),
    'FW3': dict(len=41, id=(0, 9), type=(16, 17), date=(9, 16), dfmt='ordinal', w=(17, 24), wu='dlb', st=(24, 25)),
}


def parse_south(text):
    seq = None
    layout = None
    recs = []
    by_len = {v['len']: k for k, v in LAYOUTS.items()}
    for line in lines_of(text):
        if '\x0c' in line or line.startswith('SOUTH DEPOT'):
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m:
                layout = m.group(1).upper()
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not line.strip():
            continue
        name = by_len.get(len(line))
        if name is None:
            if layout not in LAYOUTS:
                continue
            name = layout
            line = line.ljust(LAYOUTS[name]['len'])[:LAYOUTS[name]['len']]
        L = LAYOUTS[name]
        f = lambda k: line[L[k][0]:L[k][1]]
        idtxt = f('id')
        kind = kind_of(f('type'))
        if kind == 'void':
            recs.append(make(idtxt, 'void', None, None, None))
            continue
        try:
            raw = Decimal(int(f('w')))
            kg = {'g': raw * UNIT_KG['g'], 'cg': raw / 100,
                  'dlb': raw / 10 * UNIT_KG['lb']}[L['wu']]
        except Exception:
            kg = None
        try:
            ds = f('date')
            if L['dfmt'] == 'ordinal':
                date = dt.date(int(ds[:4]), 1, 1) + dt.timedelta(days=int(ds[4:]) - 1)
            else:
                date = dt.date(int(ds[:4]), int(ds[4:6]), int(ds[6:8]))
        except Exception:
            date = None
        recs.append(make(idtxt, kind, norm_status(STATUS_CODES.get(f('st').strip().upper(), f('st'))), kg, date))
    return seq, [r for r in recs if r]


# ---------- main ----------
def parse_file(depot, path):
    b = read_bytes(path)
    if depot == 'central':
        return parse_central(b)
    text = decode(b)
    if depot == 'north':
        return parse_north(text)
    if depot == 'south':
        return parse_south(text)
    if depot == 'harbor':
        return parse_delimited(depot, text)
    return parse_delimited(depot, text)


def sniff_depot_parse(depot, path):
    if depot in CFG or depot in ('central', 'north', 'south'):
        return parse_file(depot, path)
    raise ValueError('unknown depot ' + depot)


def main(data_dir, out_file):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if os.path.isfile(p):
            files.setdefault(name.split('-')[0], []).append(p)
    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        exports = []
        for i, p in enumerate(paths):
            seq, recs = sniff_depot_parse(depot, p)
            exports.append((seq if seq is not None else float('inf'), i, recs))
        exports.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exports:
            for r in recs:
                n = r['num']
                if r['kind'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['kind'] == 'correction':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    rank = {d: i for i, d in enumerate(ORDER)}
    depots_sorted = sorted(files, key=lambda d: (rank.get(d, len(ORDER)), d))
    owners = {}
    for d in depots_sorted:
        for n in current[d]:
            owners.setdefault(n, []).append(d)
    handovers = sum(1 for o in owners.values() if len(o) > 1)
    dep = {d: [0, Decimal(0)] for d in files}
    months = {}
    for n, o in owners.items():
        r = current[o[0]][n]
        if r['status'] not in ('delivered', 'delivered_late'):
            continue
        kg = r['kg'] if r['kg'] is not None else Decimal(0)
        dep[o[0]][0] += 1
        dep[o[0]][1] += kg
        if r['date'] is not None:
            m = months.setdefault('%04d-%02d' % (r['date'].year, r['date'].month), [0, Decimal(0)])
            m[0] += 1
            m[1] += kg
    q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    out = {
        'depots': {d: {'shipments': dep[d][0], 'total_kg': q(dep[d][1])} for d in sorted(dep)},
        'months': {m: {'shipments': months[m][0], 'total_kg': q(months[m][1])} for m in sorted(months)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as fh:
        json.dump(out, fh, indent=2)
        fh.write('\n')


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
E
